from pathlib import Path
import json, html, zipfile
ROOT=Path(__file__).resolve().parent.parent
scenes=json.loads((ROOT/'scenes.json').read_text())
gallery='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Circuit · 45 responsive design references</title><style>@import url('assets/inter.css');*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#142236;font:15px/1.5 Inter,Arial,sans-serif}a{color:#17476e}header{padding:36px 5%;background:#142236;color:white}header p{color:#ccd8e6;max-width:800px}header a{color:white}.eyebrow{text-transform:uppercase;font-size:12px;letter-spacing:.15em;color:#b6ccdf}h1{font-size:40px;letter-spacing:-.05em;margin:8px 0 12px}nav{display:flex;gap:24px;flex-wrap:wrap;margin-top:22px}.layout{display:grid;grid-template-columns:275px minmax(0,1fr);max-width:1800px;margin:auto}.scenes{padding:22px 16px;border-right:1px solid #ced6e0;background:white}.scenes button{display:block;width:100%;text-align:left;padding:13px 12px;border:0;background:none;font:inherit;font-size:13px;color:#142236;cursor:pointer;border-radius:4px}.scenes button.active{background:#e7edf5;font-weight:700;color:#17476e}main{padding:32px;min-width:0}h2{font-size:25px;letter-spacing:-.035em;margin:0 0 12px}.tools{display:flex;gap:12px;flex-wrap:wrap;margin:22px 0}.tools button{min-height:42px;padding:10px 16px;border:1px solid #67768b;border-radius:4px;color:#17476e;background:white;cursor:pointer;font:inherit}.tools button.active{background:#17476e;color:white}.links{display:flex;gap:20px;flex-wrap:wrap;margin:15px 0;font-size:13px}.preview{padding:18px;background:#e7edf5;border:1px solid #ced6e0;overflow:auto}.preview img{display:block;max-width:100%;height:auto;margin:auto;background:white}.note{font-size:13px;color:#4c5b70}.matrix{padding:32px 5%;border-top:1px solid #ced6e0;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.matrix a{display:block;text-decoration:none;background:white;border:1px solid #ced6e0;padding:14px}.matrix img{width:100%;aspect-ratio:1.7;object-fit:cover;object-position:top;border:1px solid #e7edf5}.matrix strong{display:block;margin-top:12px;font-size:14px}.matrix p{font-size:12px;color:#4c5b70}@media(max-width:900px){.layout{grid-template-columns:1fr}.scenes{display:flex;overflow:auto;gap:8px;border-bottom:1px solid #ced6e0}.scenes button{min-width:180px}.matrix{grid-template-columns:1fr 1fr}}@media(max-width:600px){h1{font-size:32px}header{padding:28px 20px}main{padding:24px 16px}.matrix{grid-template-columns:1fr;padding:24px 16px}.preview{padding:8px}}</style></head><body><header><p class="eyebrow">LetBuyy / forge / Milestone 1</p><h1>Circuit. Facts before connection.</h1><p>15 connected scenes · 45 independently rendered PNGs · 15 additional device boards. A design storybook for electronics and accessories. Proposed capabilities are documented; commerce is not implemented by this artifact.</p><nav><a href="Circuit-45-mockups.zip">Download 45 PNGs</a><a href="prototype-index.html">Editable responsive source</a><a href="README.md">Design handoff</a><a href="comparisons/index.html">Research & neutral comparisons</a><a href="validation.json">Validation</a></nav></header><div class="layout"><aside class="scenes" aria-label="Scenes">'''
gallery+=''.join(f'<button data-scene="{s["id"]}">{s["number"]:02} · {html.escape(s["title"])}</button>' for s in scenes)
gallery+='''</aside><main><h2 id="title"></h2><p id="note" class="note"></p><div class="tools"><button data-device="board">Three-device board</button><button data-device="desktop">Desktop</button><button data-device="tablet">Tablet</button><button data-device="mobile">Mobile</button></div><div class="links"><a id="full" target="_blank">Open full PNG</a><a id="source" target="_blank">Open source scene</a><a id="download" download>Save PNG</a></div><p class="note" id="dimensions"></p><div class="preview"><img id="preview" alt="Selected Circuit design scene"></div></main></div><section class="matrix">'''
gallery+=''.join(f'<a href="#scene={s["id"]}&device=board" data-overview="{s["id"]}"><img loading="lazy" src="{s["board"]}" alt="{html.escape(s["title"])} three-device board"><strong>{s["number"]:02} · {html.escape(s["title"])}</strong><p>{html.escape(s["note"])}</p></a>' for s in scenes)
gallery+='</section><script>const scenes='+json.dumps(scenes)+''';let selected=scenes[0],device='board';function render(){const p=new URLSearchParams(location.hash.slice(1));selected=scenes.find(s=>s.id===p.get('scene'))||selected;device=p.get('device')||device;document.querySelector('#title').textContent=selected.title;document.querySelector('#note').textContent=selected.note;let file=device==='board'?selected.board:selected.images[device];const im=document.querySelector('#preview');im.src=file;im.alt=selected.title+' — '+device;for(const id of ['full','download'])document.querySelector('#'+id).href=file;document.querySelector('#source').href=selected.source;document.querySelector('#dimensions').textContent=device==='board'?'Composite for comparison. Open an individual PNG to inspect text at native size.':({desktop:'1440 × 1000',tablet:'834 × 1112',mobile:'390 × 844'}[device])+' CSS viewport · DPR 1 · full-page PNG';document.querySelectorAll('[data-scene]').forEach(b=>b.classList.toggle('active',b.dataset.scene===selected.id));document.querySelectorAll('[data-device]').forEach(b=>b.classList.toggle('active',b.dataset.device===device));}document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>location.hash='scene='+b.dataset.scene+'&device='+device);document.querySelectorAll('[data-device]').forEach(b=>b.onclick=()=>location.hash='scene='+selected.id+'&device='+b.dataset.device);document.querySelectorAll('[data-overview]').forEach(a=>a.onclick=()=>scrollTo({top:0}));addEventListener('hashchange',render);render();</script></body></html>'''
(ROOT/'index.html').write_text(gallery)
images=sorted((ROOT/'images').glob('*.png'))
if len(images)==45:
 with zipfile.ZipFile(ROOT/'Circuit-45-mockups.zip','w',zipfile.ZIP_DEFLATED) as z:
  for image in images:z.write(image,'images/'+image.name)
 print('Gallery + ZIP built,',len(images),'images')
else: print('Gallery built; ZIP awaits 45 images')
